const { data: Services } = await useAsyncData('Services', () =&gt; {
    return $directus.items('Services').readByQuery()
})
// console.log($directus);
&lt;/script&gt;
</code></pre>
<p>I am getting this without proper P and H tags which I set in my markdown content. Its looking raw text.. I want to make it html format like it should look.
How can I use markdown here ? In NUXT2, we can use markdownit module... but in NUXT3, its not compatible.
I read NUXT content module docs but can not find what I am looking for.</p>

answer:
To display markdown content as HTML tags in your NUXT 3 application, you need to install and configure the `markdown-it` package. Here's how you can do it:

```python
# Install markdown-it package
npm install markdown-it

# Import markdown-it in your page component
import MarkdownIt from 'markdown-it'

# Create an instance of markdown-it
md = MarkdownIt()

# Define a custom renderer for headings (e.g., h2 to h6)
def heading Renderer(tokens, idx, opts, env, self):
    if tokens[idx].tag == 'h2':
        return '<h2>' + self.renderToken(tokens, idx, opts) + '</h2>'
    elif tokens[idx].tag == 'h3':
        return '<h3>' + self.renderToken(tokens, idx, opts) + '</h3>'
    elif tokens[idx].tag == 'h4':
        return '<h4>' + self.renderToken(tokens, idx, opts) + '</h4>'
    elif tokens[idx].tag == 'h5':
        return '<h5>' + self.renderToken(tokens, idx, opts) + '</h5>'
    elif tokens[idx].tag == 'h6':
        return '<h6>' + self.renderToken(tokens, idx, opts) + '</h6>'

# Register the custom renderer for headings
md.renderer.rules.heading_open = headingRenderer

# Function to render markdown content
async function renderMarkdown(content) {
    return md.render(content);
}

# Usage example in your page component
<template>
  <div>
    <h1>{{ title }}</h1>
    <div v-for="(item, index) in services" :key="index">
      {{ item.title }}
      <p>{{ await renderMarkdown(item.test_data) }}</p>
    </div>
  </div>
</template>

<script>
import { defineComponent, onMounted } from '#vue';
import { useNuxtApp } from '#app';

export default defineComponent({
  setup() {
    const { $directus } = useNuxtApp();
    const { data: services } = await useAsyncData('Services', () => {
      return $directus.items('Services').readByQuery();
    });

    onMounted(async () => {
      // Fetching title dynamically
      const titleResponse = await $directus.item('Services', services[0]?.id).read();
      this.title = titleResponse?.title;
    });

    return {
      services,
      title: '',
      async renderMarkdown(content) {
        return md.render(content);
      }
    };
  }
});
</script>
```

### Explanation:
1. **Install Markdown-it**: First, you need to install the `markdown-it` package using npm or yarn.
2. **Create an Instance**: Import the `MarkdownIt` class and create an instance of it.
3. **Custom Renderer**: Define a custom renderer for headings (`h2` to `h6`) to convert them into HTML tags.
4. **Register Custom Renderer**: Register the custom renderer with the `markdown-it` instance.
5. **Render Markdown Content**: Create a function `renderMarkdown` that uses the `markdown-it` instance to render markdown content.
6. **Usage Example**: In your Vue template, use the `v-for` directive to iterate over the services array and render the test_data using the `renderMarkdown` function.

This approach ensures that your markdown content is rendered as HTML tags in your NUXT 3 application.

