        $pos = strlen($matches[0]??='') -1;
        if ($current and !str_starts_with($name, $current))
         {
            if ($loop || $pos)
             {
                $newFuncs[$current] = processRegexArray($newFuncs[$current]);
                $loop = false;
             }
            $current = false;
         }
        if ($pos)
