<p>Im trying to move from a older project to one tht uses the app directory. I tried to add the SessionProvider code that was in the original _app.js file to the root layout but Im not having any luck</p>

answer:
To resolve the issue of `useSession` being unavailable in Server Components and needing to wrap it within a `SessionProvider`, you need to ensure that your layout component is a Client Component. This means you should use the `useEffect` hook to fetch the session data once the component mounts.

Here's how you can modify your `layout.tsx` to achieve this:

```typescript
import Image from 'next/image';
import { SessionProvider } from 'next-auth/react';
import { ReactNode } from 'react';
import React from 'react';

import './globals.css';
import Link from 'next/link';

type Props = {
  children: ReactNode;
  session: any;
};

export default function Layout({ children, session }: Props) {
  useEffect(() => {
    // Fetch session data once the component mounts
    if (!session) {
      signIn('google', { callbackUrl: '/account' });
    }
  }, []);

  return (
    <html lang="en">
      <head />
      <body>
        <div className="mx-auto">
          <div className="flex flex-row flex-wrap">
            <aside className="w-full sm:w-1/3 md:w-1/5 xl:w-1/6 border-r-2 border-[#F845C6]">
              <div className="sticky top-0 p-4 w-full">
                <ul className="flex flex-col overflow-hidden">
                  <li className="m-5 text-center">
                    <Link href="/login">LOGO</Link>
                  </li>
                  <li className="m-5 text-center">
                    <Link href="/">Dashboard</Link>
                  </li>
                  <li className="m-5 text-center">
                    <Link href="/tasks">Tasks</Link>
                  </li>
                  <li className="m-5 text-center">
                    <Link href="/reporting">Reporting</Link>
                  </li>
                </ul>
              </div>
            </aside>

            <div className="w-full sm:w-2/3 md:w-4/5 xl:w-5/6">{children}</div>
          </div>
        </div>
      </body>
    </html>
  );
}

export function getLayout(page: any) {
  const { session } = page.props;

  return (
    <SessionProvider session={session}>
      <Layout session={session}>{page}</Layout>
    </SessionProvider>
  );
}
```

In this modified `layout.tsx`, we added an `useEffect` hook that checks if the session exists. If the session does not exist, it calls `signIn` with the provider (`'google'`) and sets the `callbackUrl` to `/account`.

By making sure your layout component is a Client Component, you can now use `useSession` without encountering the `React Context is unavailable in Server Components` error.

